/**
 * Constraints for the `useUserMedia` hook.
 * Defines the video and audio settings for the media stream.
 */
export interface UseUserMediaConstraints {
  /**
   * Boolean or specific constraints for the video track.
   * @default true
   */
  video?: boolean | MediaTrackConstraints;
  /**
   * Boolean or specific constraints for the audio track.
   * @default true
   */
  audio?: boolean | MediaTrackConstraints;
}

/**
 * Return type for the `useUserMedia` hook.
 */
export interface UseUserMediaReturn {
  /**
   * The current MediaStream object, or null if no stream is active.
   */
  stream: MediaStream | null;
  /**
   * An error message string if the media capture failed, or null otherwise.
   */
  error: string | null;
  /**
   * A boolean indicating if the media stream is currently loading (requesting permission).
   */
  isLoading: boolean;
  /**
   * A boolean indicating if the `getUserMedia` API is supported in the current environment.
   */
  isSupported: boolean;
  /**
   * Function to start capturing media. Accepts optional constraints to override defaults.
   */
  startCapture: (constraints?: UseUserMediaConstraints) => Promise<void>;
  /**
   * Function to stop the current media capture and release tracks.
   */
  stopCapture: () => void;
}

const DEFAULT_CONSTRAINTS: UseUserMediaConstraints = {
  video: true,
  audio: true,
};

/**
 * Custom hook that captures audio and video from the user's device.
 * It handles permission errors, stream management, and cleanup automatically.
 *
 * @category sensors
 * @param initialConstraints - The initial constraints for audio and video.
 * @returns {UseUserMediaReturn} An object containing the stream, error state, and control functions.
 * @see [Documentation](https://sse-hooks.vercel.app/docs/hooks/use-user-media)
 * @public
 */
export const useUserMedia = (
  initialConstraints: UseUserMediaConstraints = DEFAULT_CONSTRAINTS,
): UseUserMediaReturn => {
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const streamRef = useRef<MediaStream | null>(null);

  const isSupported =
    typeof navigator !== "undefined" &&
    "mediaDevices" in navigator &&
    "getUserMedia" in navigator.mediaDevices;

  const stopCapture = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => {
        track.stop();
      });
      streamRef.current = null;
      setStream(null);
    }
    setError(null);
  }, []);

  const startCapture = useCallback(
    async (constraints: UseUserMediaConstraints = initialConstraints) => {
      if (!isSupported) {
        setError("getUserMedia is not supported in this browser");
        return;
      }

      // Stop any existing stream
      stopCapture();

      setIsLoading(true);
      setError(null);

      try {
        const mediaStream =
          await navigator.mediaDevices.getUserMedia(constraints);
        streamRef.current = mediaStream;
        setStream(mediaStream);
      } catch (err: any) {
        let errorMessage = "Failed to access media devices";

        if (err instanceof Error) {
          switch (err.name) {
            case "NotAllowedError":
              errorMessage =
                "Permission denied. Please allow camera/microphone access.";
              break;
            case "NotFoundError":
              errorMessage = "No camera or microphone found.";
              break;
            case "NotReadableError":
              errorMessage = "Camera or microphone is already in use.";
              break;
            case "OverconstrainedError":
              errorMessage =
                "Camera or microphone constraints cannot be satisfied.";
              break;
            case "SecurityError":
              errorMessage = "Security error. Make sure you're using HTTPS.";
              break;
            case "AbortError":
              errorMessage = "Media access was aborted.";
              break;
            default:
              errorMessage = err.message || errorMessage;
          }
        }

        setError(errorMessage);
      } finally {
        setIsLoading(false);
      }
    },
    [isSupported, initialConstraints, stopCapture],
  );

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stopCapture();
    };
  }, [stopCapture]);

  return {
    stream,
    error,
    isLoading,
    isSupported,
    startCapture,
    stopCapture,
  };
};

